"""Independent structural validation of an audit response.

Checks internal consistency of both witnesses (walk validity, non-done
states, loop closure, fairness conditions) - not the verdicts themselves.
"""
import brute

def validate(P, R, D, inputs, states, edges, start, fair, resp):
    n = len(states)
    safe, done, allt, en = brute.build(P, R, D, inputs, states, edges, start, fair)
    errs = []
    if set(resp.keys()) != set(["safe", "safety", "terminates", "liveness"]):
        errs.append("bad keys")
        return errs
    tot = 0
    # ---- safety witness
    if resp["safe"]:
        if resp["safety"] is not None:
            errs.append("safety not null though safe")
    else:
        w = resp["safety"]
        if not isinstance(w, dict) or set(w.keys()) != {"prefix"}:
            errs.append("bad safety witness shape")
        else:
            tot += len(w["prefix"])
            cur = start
            for eid in w["prefix"]:
                if not (0 <= eid < len(edges)):
                    errs.append("bad safety edge id %r" % (eid,)); break
                if edges[eid][0] != cur:
                    errs.append("safety walk mismatch at %r" % (eid,)); break
                cur = edges[eid][2]
            else:
                if safe[cur]:
                    errs.append("safety endpoint is safe")
    # ---- liveness witness
    if resp["terminates"]:
        if resp["liveness"] is not None:
            errs.append("liveness not null though terminating")
    else:
        w = resp["liveness"]
        if not isinstance(w, dict) or set(w.keys()) != {"prefix", "loop"}:
            errs.append("bad liveness witness shape")
        else:
            tot += len(w["prefix"]) + len(w["loop"])
            if not isinstance(w["loop"], list) or len(w["loop"]) < 1:
                errs.append("empty loop")
            else:
                cur = start
                for eid in w["prefix"]:
                    if not (0 <= eid < len(edges)):
                        errs.append("bad prefix edge id %r" % (eid,)); break
                    if edges[eid][0] != cur:
                        errs.append("prefix walk mismatch at %r" % (eid,)); break
                    cur = edges[eid][2]
                    if done[cur]:
                        errs.append("prefix visits done state"); break
                else:
                    e2 = cur
                    loopstates = [e2]
                    for eid in w["loop"]:
                        if eid == -1:
                            st = cur
                        elif not (0 <= eid < len(edges)):
                            errs.append("bad loop edge id %r" % (eid,)); break
                        elif edges[eid][0] != cur:
                            errs.append("loop walk mismatch at %r" % (eid,)); break
                        else:
                            cur = edges[eid][2]
                        loopstates.append(cur)
                    else:
                        if any(done[s] for s in loopstates):
                            errs.append("loop visits done state")
                        if cur != e2:
                            errs.append("loop does not close at prefix endpoint")
                        Vset = set(loopstates)
                        for (a, mode) in fair:
                            enset = [x for x in Vset if a in en[x]]
                            loopedges = [eid for eid in w["loop"]
                                         if eid != -1 and edges[eid][1] == a]
                            if mode == "strong":
                                if enset and not loopedges:
                                    errs.append("strong fairness %s violated" % a)
                            else:
                                if len(enset) == len(Vset) and not loopedges:
                                    errs.append("weak fairness %s violated" % a)
    if tot > 1000000:
        errs.append("too many edge ids")
    return errs
